  <div class="bar center"><span>KYC Documents Required for Opening Current Accounts:</span></div>
  <table class="tbl" style="font-size:7.2px;line-height:1.4">
    <tr><th style="width:30px">Sl No</th><th style="width:110px">Type of Entity</th><th>KYC Documents</th></tr>
